function numbersIn(text: string): Set<string> {
  return new Set(text.match(/\d+(?:[.,]\d+)?%?/g) ?? []);
}

export function findFabricatedNumbers(
  letter: Array<{ key: string; prose: string }>,
  aggregates: DailyDigestAggregates,
): string[] {
  const allowed = numbersIn(JSON.stringify(aggregates));
  const out: string[] = [];
  for (const section of letter) {
    for (const n of numbersIn(section.prose)) {
      if (!allowed.has(n)) out.push(`${section.key}: ${n}`);
    }
  }
  return out;
}

